const oauthModalList=q('#oauth-provider-list');if(oauthModalList&&!q('#oauth-account-label'))oauthModalList.insertAdjacentHTML('beforebegin','<label class="field wide" id="oauth-account-label-field">账号备注（可选）<input id="oauth-account-label" autocomplete="off" placeholder="例如：Claude 工作账号、Grok 个人账号"></label>');
const esc=function(v){return String(v||'').replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})};
const waitForDashboardRetry=function(ms){return new Promise(function(resolve){window.setTimeout(resolve,ms)})};
const api=async function(url,options){const requestOptions=Object.assign({credentials:'same-origin',cache:'no-store'},options||{}),canRetry=!requestOptions.method||String(requestOptions.method).toUpperCase()==='GET',retryDelays=[250,750,1500];for(let attempt=0;attempt<=(canRetry?retryDelays.length:0);attempt++){let response;try{response=await fetch(url,requestOptions)}catch(error){if(!canRetry||attempt===retryDelays.length)throw error;await waitForDashboardRetry(retryDelays[attempt]);continue}const data=await response.json().catch(function(){return {}});if(response.ok)return data;if(canRetry&&response.status>=500&&attempt<retryDelays.length){await waitForDashboardRetry(retryDelays[attempt]);continue}throw new Error(data.error||'请求失败')}throw new Error('请求失败')};
const state={presets:[],providers:[],models:[],candidate:null,voice:null,gatewayActive:true,providerDiscoveryModels:[],providerDiscoveryLoaded:false,providerDiscoveryExistingModels:new Set(),providerDiscoveryProvider:null};
// Keep the subscription entry point alive even if an unrelated optional view
// fails during boot. The dashboard is a single inline script, so a later
// initialization exception would otherwise prevent the old, late bindings
// below from ever being installed.
document.addEventListener('click',function(event){
  const target=event.target&&event.target.closest?event.target.closest('#add-oauth-button,[data-oauth-add],[data-oauth-login],[data-oauth-capture],[data-oauth-cancel],[data-oauth-refresh-provider]'):null;
  if(!target)return;
  event.preventDefault();
  if(target.id==='add-oauth-button'||target.hasAttribute('data-oauth-add')){
    openOAuthAddModal(target.dataset.oauthAdd||'');
    return;
  }
  if(target.hasAttribute('data-oauth-login')){
    startOAuthLogin(target.dataset.oauthLogin,target);
    return;
  }
  if(target.hasAttribute('data-oauth-capture')){
    captureOAuthAccount(target.dataset.oauthCapture,target);
    return;
  }
  if(target.hasAttribute('data-oauth-cancel')){
    cancelOAuthLogin(target.dataset.oauthCancel,target);
    return;
  }
  refreshOAuthStatus(target);
});
document.head.insertAdjacentHTML('beforeend','<style>.language-toggle{width:100%;margin:18px 0 0;padding:9px 12px;border:1px solid #333;border-radius:9px;background:#151515;color:#d7d7d7;font:inherit;font-size:12px;cursor:pointer}.language-toggle:hover{background:#242424;color:#fff}.oauth-provider-list{display:grid;gap:12px;margin-top:14px}.oauth-provider-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:18px;padding:16px}.oauth-provider-row-copy{display:grid;gap:8px;min-width:0}.oauth-provider-title{display:flex;align-items:center;gap:10px;min-height:32px}.oauth-provider-title b{display:block;font-size:16px;line-height:1.25}.oauth-provider-row-copy small{display:block;margin-top:0!important;line-height:1.5}.oauth-account-items{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:0}.oauth-account-item{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0;min-height:38px;border:1px solid #383838;border-radius:9px;background:#171717;padding:7px 10px;color:#ddd;font-size:11px}.oauth-account-item b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.oauth-account-item small{color:#8fe0ae;white-space:nowrap}.oauth-account-empty{display:block;margin-top:0;color:#888;font-size:11px}.oauth-provider-row>.button{align-self:start;margin-top:1px}@media(max-width:720px){.oauth-provider-row{grid-template-columns:1fr}.oauth-provider-row>.button{width:100%;margin-top:0}.oauth-account-items{grid-template-columns:1fr}}</style>');
