function installLivePickerOrb(){if(q('#live-picker-orb'))return;document.body.insertAdjacentHTML('beforeend','<div id="live-picker-orb" class="live-picker-orb hidden"><button id="live-picker-orb-button" type="button" aria-label="打开 GPT-Live 模型选择">✦<span>Live</span></button><div id="live-picker-popover" class="live-picker-popover hidden"><h3>选择 GPT-Live 执行模型</h3><p id="live-picker-message">等待 Live 准备任务…</p><div id="live-picker-models" class="live-picker-models"></div><div class="live-picker-footer"><button id="live-picker-cancel" type="button">关闭</button></div></div></div>');const orb=q('#live-picker-orb'),orbButton=q('#live-picker-orb-button'),popover=q('#live-picker-popover');orbButton.onclick=function(){if(orb.dataset.dragged==='1'){orb.dataset.dragged='';return}popover.classList.toggle('hidden')};q('#live-picker-cancel').onclick=function(){popover.classList.add('hidden')};let drag=null;try{const saved=JSON.parse(localStorage.getItem('opencodex.live_picker_position')||'null');if(saved&&Number.isFinite(saved.left)&&Number.isFinite(saved.top)){orb.style.left=saved.left+'px';orb.style.top=saved.top+'px';orb.style.right='auto';orb.style.bottom='auto'}}catch(e){}orbButton.onpointerdown=function(event){drag={startX:event.clientX,startY:event.clientY,left:orb.getBoundingClientRect().left,top:orb.getBoundingClientRect().top,moved:false};orb.classList.add('dragging');orbButton.setPointerCapture(event.pointerId);event.preventDefault()};orbButton.onpointermove=function(event){if(!drag)return;const dx=event.clientX-drag.startX,dy=event.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(!drag.moved)return;const maxLeft=Math.max(8,window.innerWidth-orb.offsetWidth-8),maxTop=Math.max(8,window.innerHeight-orb.offsetHeight-8),left=Math.min(maxLeft,Math.max(8,drag.left+dx)),top=Math.min(maxTop,Math.max(8,drag.top+dy));orb.style.left=left+'px';orb.style.top=top+'px';orb.style.right='auto';orb.style.bottom='auto'};orbButton.onpointerup=function(){if(!drag)return;orb.classList.remove('dragging');if(drag.moved){orb.dataset.dragged='1';try{localStorage.setItem('opencodex.live_picker_position',JSON.stringify({left:parseFloat(orb.style.left),top:parseFloat(orb.style.top)}))}catch(e){}}drag=null};}
function renderLivePicker(data){const orb=q('#live-picker-orb'),popover=q('#live-picker-popover'),message=q('#live-picker-message'),models=q('#live-picker-models');if(!orb)return;livePickerState.enabled=data.enabled===true;livePickerState.pending=data.pending===true;if(!livePickerState.enabled){livePickerState.requestId='';orb.classList.add('hidden');popover.classList.add('hidden');models.innerHTML='';return}orb.classList.remove('hidden');orb.classList.toggle('attention',livePickerState.pending);if(!livePickerState.pending){message.textContent='已开启，等待 Live 准备任务…';models.innerHTML='';return}message.textContent='Live 已准备把任务交给 Codex，请选择执行模型：';if(livePickerState.requestId!==data.request_id){livePickerState.requestId=data.request_id||'';models.innerHTML=(data.models||[]).map(function(model){return '<button type="button" data-live-picker-model="'+esc(model)+'">'+esc(model)+'</button>'}).join('');popover.classList.add('hidden');models.querySelectorAll('[data-live-picker-model]').forEach(function(button){button.onclick=function(){resolveLivePickerModel(button.dataset.livePickerModel)}})}}
