function installLivePickerOrbAnimation(){const button=q('#live-picker-orb-button');if(!button||button.querySelector('canvas'))return;button.textContent='';const canvas=document.createElement('canvas');canvas.width=112;canvas.height=112;canvas.setAttribute('aria-hidden','true');button.appendChild(canvas);const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)return;let phase=0;const clamp=function(value){return Math.min(1,Math.max(0,value))};const cloudWeight=function(u,v,seed,speed){const warpedU=u+0.13*Math.sin(v*7.2+phase*speed+seed)+0.06*Math.cos(u*4.4-phase*speed*.7+seed*1.7);const warpedV=v+0.14*Math.cos(u*6.1-phase*speed*.9+seed)+0.05*Math.sin(v*5.3+phase*speed*.6+seed*1.2);const wave=.54*Math.sin(warpedU*8+warpedV*2.1+phase*speed)+.31*Math.sin(warpedV*9.2-warpedU*3.4-phase*speed*.72+seed)+.21*Math.sin((warpedU+warpedV)*7.1+phase*speed*.48+seed*2.3);return Math.pow(clamp((wave+.30)*1.2),2.2)};const render=function(){if(!document.body.contains(canvas))return;phase+=.018;const size=112,image=ctx.createImageData(size,size),pixels=image.data;for(let y=0;y<size;y++){for(let x=0;x<size;x++){const u=x/(size-1),v=y/(size-1),cyan=cloudWeight(u,v,.4,1),pink=cloudWeight(u,v,2.1,.83),blue=cloudWeight(u,v,4.3,1.17),violet=cloudWeight(u,v,6.4,.69),total=cyan+pink+blue+violet,alpha=clamp(.21+total*.23),red=(pink+blue*.16+violet*.52)/Math.max(total,.001),green=(cyan*.95+blue*.42+violet*.30+pink*.12)/Math.max(total,.001),blueChannel=(cyan*.90+pink*.72+blue+violet)/Math.max(total,.001),index=(y*size+x)*4,brightness=1.10;pixels[index]=clamp(red*alpha*brightness)*255;pixels[index+1]=clamp(green*alpha*brightness)*255;pixels[index+2]=clamp(blueChannel*alpha*brightness)*255;pixels[index+3]=alpha*255}}ctx.putImageData(image,0,0);requestAnimationFrame(render)};requestAnimationFrame(render)}
function renderLivePicker(data){const orb=q('#live-picker-orb'),popover=q('#live-picker-popover'),message=q('#live-picker-message'),models=q('#live-picker-models');if(!orb)return;livePickerState.enabled=data.enabled===true;livePickerState.pending=data.pending===true;if(!livePickerState.enabled){livePickerState.requestId='';livePickerState.modelsKey='';orb.classList.add('hidden');popover.classList.add('hidden');models.innerHTML='';return}orb.classList.remove('hidden');orb.classList.toggle('attention',livePickerState.pending);const available=Array.isArray(data.models)?data.models:[],selected=typeof data.selected_model==='string'?data.selected_model:'',key=available.join('\\n')+'|'+selected+'|'+livePickerState.pending;message.textContent=available.length?(livePickerState.pending?'Live 已准备把任务交给 Codex，请选择真正执行的模型。':'可在 Live 开始前提前选择模型…'):(livePickerState.pending?'已开启，等待 Live 准备下一个任务…':'可在 Live 开始前提前选择模型…');if(livePickerState.modelsKey===key)return;livePickerState.modelsKey=key;models.innerHTML=available.map(function(model){const isSelected=model===selected;return '<button type="button" class="'+(isSelected?'selected':'')+'" data-live-picker-model="'+esc(model)+'"><span>'+esc(model)+'</span>'+(isSelected?'<span class="live-picker-check">✓</span>':'')+'</button>'}).join('');models.querySelectorAll('[data-live-picker-model]').forEach(function(button){button.onclick=function(){resolveLivePickerModel(button.dataset.livePickerModel)}})}
async function resolveLivePickerModel(model){const requestId=livePickerState.requestId;const endpoint=requestId?'/api/live-model-picker/resolve':'/api/live-model-picker/select';const payload=requestId?{request_id:requestId,model:model}:{model:model};try{await post(endpoint,payload);livePickerState.requestId='';livePickerState.modelsKey='';await refreshLivePicker();toast('GPT-Live 已选择 '+model)}catch(e){toast(e.message,true)}}
// The original animated orb rendered several trigonometric noise fields on
// every animation frame, even while the orb was hidden. That can monopolize
// the browser renderer and make the whole dashboard appear unresponsive.
// Keep the visual affordance, but paint it once instead of running a hot loop.
function installLivePickerOrbAnimation(){
  const button=q('#live-picker-orb-button');
  if(!button||button.querySelector('canvas'))return;
  const canvas=document.createElement('canvas');canvas.width=66;canvas.height=66;canvas.setAttribute('aria-hidden','true');button.appendChild(canvas);
  const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)return;
  const gradient=ctx.createRadialGradient(21,16,2,33,33,36);gradient.addColorStop(0,'rgba(255,255,255,.92)');gradient.addColorStop(.35,'rgba(128,191,255,.72)');gradient.addColorStop(.72,'rgba(152,93,255,.62)');gradient.addColorStop(1,'rgba(17,22,42,.18)');ctx.fillStyle=gradient;ctx.fillRect(0,0,66,66);
}
// GPT-Live owns one native top-level orb in the desktop app. Keep the legacy
// web fallback in the DOM for protocol compatibility, but never display a
