function toast(message,error){const el=q('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');setTimeout(function(){el.className='toast'},3400)}
async function runButton(button,labels,task){if(button&&button.dataset.busy==='1')return;if(!button)return task();const original=button.textContent;button.disabled=true;button.dataset.busy='1';button.classList.remove('pending','success','error');button.classList.add('pending');button.textContent=labels.loading;try{const result=await task();button.classList.remove('pending');button.classList.add('success');button.textContent=labels.success;setTimeout(function(){button.classList.remove('success');button.dataset.busy='';button.disabled=false;button.textContent=original},1200);return result}catch(error){button.classList.remove('pending');button.classList.add('error');button.textContent=labels.failure;setTimeout(function(){button.classList.remove('error');button.dataset.busy='';button.disabled=false;button.textContent=original},1800);throw error}}
function post(url,data){return api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data||{})})}
function openView(view){document.querySelectorAll('.view').forEach(function(el){el.classList.remove('active')});document.querySelectorAll('[data-view]').forEach(function(el){el.classList.toggle('active',el.dataset.view===view)});q('#view-'+view).classList.add('active');try{sessionStorage.setItem('opencodex.dashboard.view',view)}catch(e){}if(view==='voice')loadVoice();if(view==='sessions')loadSessions();if(view==='logs')loadLogs()}
document.querySelectorAll('[data-view]').forEach(function(el){el.onclick=function(){openView(el.dataset.view)}});
let agentRoutingState={profiles:[],models:[],routing:{mode:'off'}};
function agentModelKey(model){return [model.provider||'',model.backend_model||'',model.slug||''].join('|')}
function agentModelLabel(model){return [model.display_name||model.slug,model.provider||'native',model.backend_model].filter(Boolean).join(' · ')}
function installAgentRoutingView(){if(q('#view-agent-routing'))return;const voiceNav=q('[data-view="voice"]');if(voiceNav)voiceNav.insertAdjacentHTML('beforebegin','<button data-view="agent-routing"><span class="ico">⇄</span>Agent 路由</button>');q('#view-gateway').insertAdjacentHTML('afterend','<section id="view-agent-routing" class="view"><div class="headline"><div><h1>Agent 路由</h1><p>由你定义职责、模型、任务类型和推理强度；重新导入模型不会覆盖这些配置。</p></div><button id="agent-routing-refresh" class="button">刷新</button></div><div class="panel-grid"><article class="card gateway-card"><div class="card-head"><div><h2>GPT-Live 分配规则</h2><p class="help">自动模式使用下方 Profile；强制模式保留当前模型选择逻辑；关闭模式使用原始默认模型。</p></div><button id="agent-routing-save" class="button primary">保存路由</button></div><div class="form-grid"><label class="field wide">模式<select id="agent-routing-mode"><option value="auto">自动分配</option><option value="forced">强制选择</option><option value="off">关闭路由</option></select></label><label class="field">默认 Profile<select id="agent-routing-default"></select></label><label class="field">强制 Profile<select id="agent-routing-forced-profile"></select></label><label class="field wide">强制模型<select id="agent-routing-forced-model"></select></label><label class="setting wide" style="justify-content:flex-start"><input id="agent-routing-strict" type="checkbox" style="width:18px;height:18px;accent-color:var(--cyan)"><span style="margin:0">严格匹配任务类型，没有匹配时不自动选其他 Profile</span></label></div></article><article class="card gateway-card"><div class="card-head"><div><h2>Agent Profile</h2><p class="help">Profile 是持久化的用户策略，不属于模型导入目录。</p></div><button id="agent-profile-new" class="button">新建</button></div><div id="agent-profile-list" class="profile-list"><div class="empty">正在读取 Profile…</div></div></article></div><article class="card gateway-card" style="margin-top:18px"><div class="card-head"><div><h2>编辑 Profile</h2><p class="help">模型可以重新绑定；推理强度支持按 Profile 设置，并可在具体任务中覆盖。</p></div><button id="agent-profile-save" class="button primary">保存 Profile</button></div><div class="form-grid"><input id="agent-profile-id" type="hidden"><label class="field">名称<input id="agent-profile-name" placeholder="代码实现"></label><label class="field">默认推理强度<select id="agent-profile-reasoning"><option value="">自动</option></select></label><label class="field wide">职责描述<textarea id="agent-profile-description" placeholder="负责修改代码、运行测试并完成实现"></textarea></label><label class="field wide">任务类型（逗号分隔）<input id="agent-profile-task-types" placeholder="coding, implementation, debugging"></label><label class="field wide">标签（逗号分隔）<input id="agent-profile-tags" placeholder="代码, 开发, 工程"></label><label class="field wide">绑定模型<select id="agent-profile-model"></select></label><label class="field wide">工具（逗号分隔）<input id="agent-profile-tools" placeholder="read, exec, apply_patch"></label><label class="setting wide" style="justify-content:flex-start"><input id="agent-profile-live" type="checkbox" style="width:18px;height:18px;accent-color:var(--cyan)"><span style="margin:0">允许 GPT-Live 使用</span></label><label class="setting wide" style="justify-content:flex-start"><input id="agent-profile-subagent" type="checkbox" style="width:18px;height:18px;accent-color:var(--cyan)"><span style="margin:0">允许子 Agent 使用</span></label><label class="setting wide" style="justify-content:flex-start"><input id="agent-profile-enabled" type="checkbox" style="width:18px;height:18px;accent-color:var(--cyan)"><span style="margin:0">启用 Profile</span></label></div></article></section>');document.head.insertAdjacentHTML('beforeend','<style>.profile-list{display:grid;gap:9px;max-height:430px;overflow:auto}.profile-card{border:1px solid var(--line);border-radius:12px;padding:12px;background:rgba(6,14,28,.25)}.profile-card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.profile-card h3{margin:0;font-size:14px}.profile-card p{margin:5px 0 0;color:var(--muted);font-size:11px;line-height:1.45}.profile-card-meta{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.profile-card-meta span{border:1px solid var(--line);border-radius:999px;padding:3px 7px;color:#b9c9de;font-size:10px}.profile-card-actions{display:flex;gap:5px}.profile-card-actions .button{padding:5px 8px;font-size:11px}</style>');q('[data-view="agent-routing"]').onclick=function(){openView('agent-routing')};q('#agent-routing-refresh').onclick=function(){loadAgentRouting()};q('#agent-profile-new').onclick=function(){clearAgentProfileForm()};q('#agent-profile-save').onclick=function(){saveAgentProfile()};q('#agent-routing-save').onclick=function(){saveAgentRoutingSettings()};q('#agent-profile-list').onclick=function(event){const edit=event.target.closest('[data-agent-edit]'),remove=event.target.closest('[data-agent-delete]');if(edit){const profile=agentRoutingState.profiles.find(function(item){return item.id===edit.dataset.agentEdit});if(profile)fillAgentProfileForm(profile)}if(remove)deleteAgentProfile(remove.dataset.agentDelete)};const oldOpenView=openView;openView=function(view){oldOpenView(view);if(view==='agent-routing')loadAgentRouting()};try{if(sessionStorage.getItem('opencodex.dashboard.view')==='agent-routing')openView('agent-routing')}catch(e){}}
function agentSplitList(value){return String(value||'').split(',').map(function(item){return item.trim()}).filter(Boolean)}
function renderAgentRouting(data){agentRoutingState={profiles:Array.isArray(data.profiles)?data.profiles:[],models:Array.isArray(data.models)?data.models:[],routing:data.routing||{mode:'off'}};const profileOptions='<option value="">不指定</option>'+agentRoutingState.profiles.map(function(profile){return '<option value="'+esc(profile.id)+'">'+esc(profile.name)+'（'+esc(profile.id)+'）</option>'}).join('');const modelOptions='<option value="">未绑定模型</option>'+agentRoutingState.models.map(function(model){return '<option value="'+esc(agentModelKey(model))+'">'+esc(agentModelLabel(model))+'</option>'}).join('');q('#agent-routing-default').innerHTML=profileOptions;q('#agent-routing-forced-profile').innerHTML=profileOptions;q('#agent-routing-forced-model').innerHTML='<option value="">不指定</option>'+agentRoutingState.models.map(function(model){return '<option value="'+esc(model.slug)+'">'+esc(agentModelLabel(model))+'</option>'}).join('');q('#agent-profile-model').innerHTML=modelOptions;q('#agent-routing-mode').value=agentRoutingState.routing.mode||'off';q('#agent-routing-default').value=agentRoutingState.routing.default_profile_id||'';q('#agent-routing-forced-profile').value=agentRoutingState.routing.forced_profile_id||'';q('#agent-routing-forced-model').value=agentRoutingState.routing.forced_model||'';q('#agent-routing-strict').checked=agentRoutingState.routing.strict_matching===true;const root=q('#agent-profile-list');root.innerHTML=agentRoutingState.profiles.length?agentRoutingState.profiles.map(function(profile){const model=profile.catalog_model,availability=profile.model_available?'可用':'模型不可用';const tasks=(profile.task_types||[]).join(' / ')||'未设置任务类型';const effort=profile.reasoning_effort?agentReasoningLabel(profile.reasoning_effort):'auto';const capability=(profile.live_enabled?'Live':'')+(profile.subagent_enabled?(profile.live_enabled?' · 子Agent':'子Agent'):'');return '<article class="profile-card"><div class="profile-card-head"><div><h3>'+esc(profile.name)+' <span class="pill">'+esc(profile.id)+'</span></h3><p>'+esc(profile.description||'未填写职责描述')+'</p></div><div class="profile-card-actions"><button type="button" class="button" data-agent-edit="'+esc(profile.id)+'">编辑</button><button type="button" class="button danger" data-agent-delete="'+esc(profile.id)+'">删除</button></div></div><p>'+esc(model?agentModelLabel(model):'未绑定模型')+' · '+esc(availability)+'</p><div class="profile-card-meta"><span>'+esc(tasks)+'</span><span>推理：'+esc(effort)+'</span><span>'+esc(capability||'未启用')+'</span></div></article>'}).join(''):'<div class="empty">还没有 Profile，请先新建。</div>';if(!q('#agent-profile-id').value)clearAgentProfileForm()}
function clearAgentProfileForm(){q('#agent-profile-id').value='';q('#agent-profile-name').value='';q('#agent-profile-description').value='';q('#agent-profile-task-types').value='';q('#agent-profile-tags').value='';q('#agent-profile-model').value='';q('#agent-profile-reasoning').innerHTML=agentReasoningOptions(null,'');q('#agent-profile-reasoning').value='';q('#agent-profile-tools').value='';q('#agent-profile-fallbacks').value='';q('#agent-profile-live').checked=true;q('#agent-profile-subagent').checked=true;q('#agent-profile-enabled').checked=true}
function fillAgentProfileForm(profile){q('#agent-profile-id').value=profile.id||'';q('#agent-profile-name').value=profile.name||'';q('#agent-profile-description').value=profile.description||'';q('#agent-profile-task-types').value=(profile.task_types||[]).join(', ');q('#agent-profile-tags').value=(profile.tags||[]).join(', ');const model=profile.catalog_model||null;q('#agent-profile-model').value=model?agentModelKey(model):'';q('#agent-profile-reasoning').innerHTML=agentReasoningOptions(model,profile.reasoning_effort||'');q('#agent-profile-reasoning').value=profile.reasoning_effort||'';q('#agent-profile-tools').value=(profile.tools||[]).join(', ');q('#agent-profile-fallbacks').value=(profile.fallback_profile_ids||[]).join(', ');q('#agent-profile-live').checked=profile.live_enabled!==false;q('#agent-profile-subagent').checked=profile.subagent_enabled!==false;q('#agent-profile-enabled').checked=profile.enabled!==false}
async function loadAgentRouting(){try{renderAgentRouting(await api('/api/agent-profiles'))}catch(e){const root=q('#agent-profile-list');if(root)root.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
async function saveAgentProfile(){const id=q('#agent-profile-id').value.trim(),name=q('#agent-profile-name').value.trim();if(!name){toast('请填写 Profile 名称',true);return}const generatedId=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||('profile-'+Date.now().toString(36));const modelKey=q('#agent-profile-model').value,model=agentRoutingState.models.find(function(item){return agentModelKey(item)===modelKey}),reasoning=q('#agent-profile-reasoning').value||'';if(!agentReasoningSupported(model,reasoning)){toast('该模型未返回此推理强度，请选择模型支持的等级或自动',true);return}const payload={id:id||generatedId,name:name,description:q('#agent-profile-description').value.trim(),task_types:agentSplitList(q('#agent-profile-task-types').value),tags:agentSplitList(q('#agent-profile-tags').value),model_ref:model?{provider:model.provider,backend_model:model.backend_model,catalog_slug:model.slug}:null,reasoning_effort:reasoning||undefined,tools:agentSplitList(q('#agent-profile-tools').value),fallback_profile_ids:agentSplitList(q('#agent-profile-fallbacks').value),live_enabled:q('#agent-profile-live').checked,subagent_enabled:q('#agent-profile-subagent').checked,enabled:q('#agent-profile-enabled').checked};try{await post('/api/agent-profiles',payload);toast('Profile 已保存');await loadAgentRouting();fillAgentProfileForm(agentRoutingState.profiles.find(function(item){return item.id===payload.id})||payload)}catch(e){toast(e.message,true)}}
async function deleteAgentProfile(id){if(!id)return;try{await api('/api/agent-profiles/'+encodeURIComponent(id),{method:'DELETE'});toast('Profile 已删除');clearAgentProfileForm();await loadAgentRouting()}catch(e){toast(e.message,true)}}
async function saveAgentRoutingSettings(){try{const settings=await post('/api/agent-routing/settings',{mode:q('#agent-routing-mode').value,default_profile_id:q('#agent-routing-default').value||null,forced_profile_id:q('#agent-routing-forced-profile').value||null,forced_model:q('#agent-routing-forced-model').value||null,strict_matching:q('#agent-routing-strict').checked});toast('路由设置已保存');await loadAgentRouting();return settings}catch(e){toast(e.message,true)}}
