function agentModelProfileFor(model,profiles){return profiles.find(function(profile){const ref=profile.model_ref||{};return profile.catalog_model&&profile.catalog_model.slug===model.slug||(ref.catalog_slug&&ref.catalog_slug===model.slug)||(ref.backend_model===model.backend_model&&(ref.provider||'')===(model.provider||''))})||null}
function agentModelProfileId(model){const basis=String(model.slug||model.backend_model||'model').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'model';return 'model-'+basis}
var AGENT_DEFAULT_REASONING_LEVELS=[{effort:'low',label:'low'},{effort:'medium',label:'medium'},{effort:'high',label:'high'}];
function agentReasoningLevels(model){const actual=Array.isArray(model&&model.supported_reasoning_levels)?model.supported_reasoning_levels.map(function(level){return {effort:String(level&&level.effort||'').trim().toLowerCase(),description:String(level&&level.description||'').trim()}}).filter(function(level){return Boolean(level.effort)}):[];if(model&&model.reasoning===false)return actual;const actualByEffort={};actual.forEach(function(level){if(!actualByEffort[level.effort])actualByEffort[level.effort]=level});const baseline=AGENT_DEFAULT_REASONING_LEVELS.map(function(level){return actualByEffort[level.effort]||{effort:level.effort,description:level.label}}),extra=actual.filter(function(level){return !AGENT_DEFAULT_REASONING_LEVELS.some(function(defaultLevel){return defaultLevel.effort===level.effort})});return baseline.concat(extra)}
function agentReasoningLabel(value){return String(value||'').trim().toLowerCase()||'auto'}
function agentReasoningOptions(model,selected){const levels=agentReasoningLevels(model),selectedValue=String(selected||'').trim().toLowerCase(),options=[{value:'',label:'auto'}].concat(levels.map(function(level){return {value:level.effort,label:agentReasoningLabel(level.effort),description:agentReasoningLabel(level.effort)}}));if(selectedValue&&!levels.some(function(level){return level.effort===selectedValue}))options.push({value:selectedValue,label:agentReasoningLabel(selectedValue),invalid:true});return options.map(function(option){return '<option value="'+esc(option.value)+'"'+(option.value===selectedValue?' selected':'')+(option.invalid?' data-invalid="true"':'')+(option.description?' title="'+esc(option.description)+'"':'')+'>'+esc(option.label)+'</option>'}).join('')}
function agentReasoningSupported(model,selected){const value=String(selected||'').trim().toLowerCase();if(!value)return true;return agentReasoningLevels(model).some(function(level){return level.effort===value})}
function agentModelDescriptionSummary(value){const text=String(value||'').replace(/\s+/g,' ').trim();return text?text.slice(0,96)+(text.length>96?'…':''):'未填写工作说明'}
function renderAgentModelCard(model,profile){
  const key=agentModelKey(model),description=profile&&profile.description||'',reasoning=profile&&profile.reasoning_effort||'',modelDefault=String(model&&model.default_reasoning_level||'').trim().toLowerCase(),reasoningBadge=reasoning?agentReasoningLabel(reasoning):modelDefault||'auto',enabled=Boolean(profile&&profile.enabled!==false),status=model.available===false?'模型不可用':'可用';
  return '<article class="card agent-model-policy-card" data-agent-model-card="'+esc(key)+'"><div class="agent-model-policy-compact"><div class="agent-model-policy-compact-main"><h3>'+esc(agentModelLabel(model))+'</h3><div class="agent-model-policy-meta"><span>'+esc(model.slug)+'</span><span>'+esc(status)+'</span><span class="agent-model-policy-summary">'+esc(agentModelDescriptionSummary(description))+'</span></div></div><div class="agent-model-policy-compact-actions"><span class="agent-model-policy-badge">推理：'+esc(reasoningBadge)+'</span><span class="agent-model-policy-badge">'+(enabled?'自动分配':'已停用')+'</span><button class="button" data-agent-model-toggle>编辑</button><button class="button danger" data-agent-model-delete>移除</button></div></div><div class="agent-model-policy-editor hidden" data-agent-model-editor><div class="form-grid"><label class="field wide">擅长领域 / 工作说明<textarea data-agent-description placeholder="例如：代码实现、调试、重构、技术分析">'+esc(description)+'</textarea></label><label class="field">默认推理强度<select data-agent-reasoning>'+agentReasoningOptions(model,reasoning)+'</select></label><label class="setting"><input type="checkbox" data-agent-auto'+(enabled?' checked':'')+'>参与自动分配</label></div><div class="agent-model-policy-actions"><button class="button primary" data-agent-model-save>保存模型配置</button></div></div></article>'
}
function renderNewAgentModelCard(){
  const configured=agentRoutingState.profiles.map(function(profile){return profile.catalog_model&&profile.catalog_model.slug||profile.model_ref&&profile.model_ref.catalog_slug||''}),available=agentRoutingState.models.filter(function(model){return configured.indexOf(model.slug)<0}),options='<option value="">请选择模型</option>'+available.map(function(model){return '<option value="'+esc(agentModelKey(model))+'">'+esc(agentModelLabel(model))+'</option>'}).join('');
  return '<article class="card agent-model-policy-card agent-model-policy-new" data-agent-model-card data-agent-model-new><div class="card-head"><div><h3>新增模型配置</h3><div class="agent-model-policy-meta"><span>保存后会出现在模型能力目录</span></div></div></div><div class="agent-model-policy-editor" data-agent-model-editor><div class="form-grid"><label class="field wide">模型<select data-agent-model-select>'+options+'</select></label><label class="field wide">擅长领域 / 工作说明<textarea data-agent-description placeholder="例如：代码实现、调试、重构、技术分析"></textarea></label><label class="field">默认推理强度<select data-agent-reasoning>'+agentReasoningOptions(null,'')+'</select></label><label class="setting"><input type="checkbox" data-agent-auto checked>参与自动分配</label></div><div class="agent-model-policy-actions"><button class="button primary" data-agent-model-save>保存模型配置</button></div></div></article>'
}
function renderAgentModelPolicies(data){
  agentRoutingState={profiles:Array.isArray(data.profiles)?data.profiles:[],models:Array.isArray(data.models)?data.models:[],routing:data.routing||{mode:'off'}};
  q('#agent-routing-mode').value=agentRoutingState.routing.mode||'off';
  q('#agent-routing-forced-model').innerHTML='<option value="">不指定</option>'+agentRoutingState.models.map(function(model){return '<option value="'+esc(model.slug)+'">'+esc(agentModelLabel(model))+'</option>'}).join('');
  q('#agent-routing-forced-model').value=agentRoutingState.routing.forced_model||'';
  const configured=agentRoutingState.models.filter(function(model){return agentModelProfileFor(model,agentRoutingState.profiles)}),root=q('#agent-model-policy-list');
  root.innerHTML=configured.length?configured.map(function(model){return renderAgentModelCard(model,agentModelProfileFor(model,agentRoutingState.profiles))}).join(''):'<div class="empty agent-model-policy-empty">还没有模型配置，请点击“新增模型”。</div>';
}
async function loadAgentModelPolicies(){try{renderAgentModelPolicies(await api('/api/agent-profiles'))}catch(e){const root=q('#agent-model-policy-list');if(root)root.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
async function saveAgentModelPolicy(card){
  if(!card)return;
  const modelKey=card.dataset.agentModelCard||card.querySelector('[data-agent-model-select]')&&card.querySelector('[data-agent-model-select]').value,model=agentRoutingState.models.find(function(item){return agentModelKey(item)===modelKey});
  if(!model){toast('请先选择模型',true);return}
  const existing=agentModelProfileFor(model,agentRoutingState.profiles),description=(card.querySelector('[data-agent-description]')||{}).value||'',reasoning=(card.querySelector('[data-agent-reasoning]')||{}).value||'',enabled=Boolean(card.querySelector('[data-agent-auto]')&&card.querySelector('[data-agent-auto]').checked);
  if(!agentReasoningSupported(model,reasoning)){toast('该模型未返回此推理强度，请选择模型支持的等级或自动',true);return}
  const payload={id:existing&&existing.id||agentModelProfileId(model),name:model.display_name||model.slug,description:description.trim(),task_types:[],tags:[],model_ref:{provider:model.provider||'',backend_model:model.backend_model,catalog_slug:model.slug},reasoning_effort:reasoning||undefined,tools:[],fallback_profile_ids:[],live_enabled:true,subagent_enabled:true,enabled};
  try{await post('/api/agent-profiles',payload);toast('模型配置已保存');await loadAgentModelPolicies()}catch(e){toast(e.message,true)}
}
async function deleteAgentModelPolicy(card){
  if(!card)return;
  const model=agentRoutingState.models.find(function(item){return agentModelKey(item)===card.dataset.agentModelCard}),profile=model&&agentModelProfileFor(model,agentRoutingState.profiles);
  if(!profile)return;
  try{await api('/api/agent-profiles/'+encodeURIComponent(profile.id),{method:'DELETE'});toast('模型配置已移除');await loadAgentModelPolicies()}catch(e){toast(e.message,true)}
}
