function oauthAccountAction(key,info){if(info&&info.login_in_progress)return '<button type="button" class="button" data-oauth-cancel="'+esc(info.login_flow_id||'')+'">取消登录</button>';if(info&&info.login_supported)return '<button type="button" class="button primary" data-oauth-login="'+esc(key)+'">添加登录账号</button>';if(info&&info.capture_supported)return '<button type="button" class="button primary" data-oauth-capture="'+esc(key)+'">捕获当前登录态</button>';return '<button type="button" class="button" disabled>暂不支持账号池</button>'}
function oauthAccountPoolHtml(info){const accounts=Array.isArray(info&&info.accounts)?info.accounts:[],count=Number(info&&info.account_count)||accounts.length;if(!accounts.length)return '<span class="oauth-account-empty">账号池为空；添加账号后才会参与轮询</span>';return '<div class="oauth-account-items">'+accounts.map(function(account){const status=account.auth_status==='ready'?'已就绪':account.auth_status==='disabled'?'已停用':'待登录';return '<span class="oauth-account-item"><b>'+esc(account.label||account.id)+'</b><small>'+esc(status)+'</small></span>'}).join('')+'</div>'}
function renderOAuthAddModal(focus){const root=q('#oauth-provider-list');if(!root)return;const data=state.subscriptionsData||{};const items=[['antigravity','Antigravity'],['grok','Grok'],['claude','Claude'],['cursor','Cursor']];root.innerHTML=items.map(function(item){const key=item[0],label=item[1],info=data[key]||{},selected=focus===key,mode=info.pool_mode==='round_robin'?'轮询中':'固定',guide=info.login_in_progress?'登录流程进行中；请完成网页登录，关闭网页会结束本次流程':info.login_supported?'可在此创建独立登录流程；':'请先在官方客户端切换账号，再捕获当前登录态；';return '<div class="oauth-provider-row '+(selected?'selected':'')+'"><div class="oauth-provider-row-copy"><div class="oauth-provider-title">'+subscriptionIcon(key)+'<b>'+esc(label)+'</b></div><small>'+esc(guide+'账号池 '+(Number(info.account_count)||0)+' 个 · '+mode)+'</small>'+oauthAccountPoolHtml(info)+'</div>'+oauthAccountAction(key,info)+'</div>'}).join('')}
let oauthModalRenderTimer=0;
function openOAuthAddModal(focus){const modal=q('#oauth-modal'),root=q('#oauth-provider-list');if(!modal)return;if(root)root.innerHTML='<div class="empty">正在读取 OAuth 账号池…</div>';modal.classList.add('show');modal.setAttribute('aria-hidden','false');window.clearTimeout(oauthModalRenderTimer);oauthModalRenderTimer=window.setTimeout(function(){if(state.subscriptionsData){renderOAuthAddModal(focus||'')}else{loadSubscriptions().then(function(){renderOAuthAddModal(focus||'')}).catch(function(error){if(root)root.innerHTML='<div class="empty">无法读取 OAuth 账号池：'+esc(error.message)+'</div>'})}},0)}
function closeOAuthAddModal(){const modal=q('#oauth-modal');if(!modal)return;modal.classList.remove('show');modal.setAttribute('aria-hidden','true')}
function oauthAccountLabel(){const input=q('#oauth-account-label');return String(input&&input.value||'').trim().slice(0,120)}
const oauthLoginPollers={};
function pollOAuthLogin(flowId,provider){if(!flowId||oauthLoginPollers[flowId])return;oauthLoginPollers[flowId]=true;let attempts=0;const check=function(){api('/api/cli-bridge/accounts/login-status/'+encodeURIComponent(flowId)).then(function(result){const login=result&&result.login||{};if(login.status==='completed'){delete oauthLoginPollers[flowId];toast((provider||login.provider||'OAuth')+' 登录完成，账号已加入账号池');return loadSubscriptions().then(function(){renderOAuthAddModal(provider||login.provider||'')})}if(login.status==='failed'){delete oauthLoginPollers[flowId];toast((provider||login.provider||'OAuth')+' 登录失败：'+(login.error||'未生成凭证'),true);return loadSubscriptions().then(function(){renderOAuthAddModal(provider||login.provider||'')})}if(attempts++>=300){delete oauthLoginPollers[flowId];toast((provider||login.provider||'OAuth')+' 登录等待超时，请重新检测登录态',true);return}window.setTimeout(check,1000)}).catch(function(error){if(attempts++>=300){delete oauthLoginPollers[flowId];toast('登录状态检测失败：'+error.message,true);return}window.setTimeout(check,1000)})};check()}
async function startOAuthLogin(provider,button){try{const result=await runButton(button,{loading:'打开登录…',success:'已打开',failure:'打开失败'},function(){return post('/api/cli-bridge/accounts/login',{provider:provider,label:oauthAccountLabel()})});toast(provider+' 登录流程已打开，请完成登录');if(result&&result.flow_id)pollOAuthLogin(result.flow_id,provider);await loadSubscriptions();renderOAuthAddModal(provider)}catch(error){toast(error.message,true)}}
