let subscriptionsRequestSerial=0;
let subscriptionsAppliedSerial=0;
async function loadSubscriptions(){
  const requestSerial=++subscriptionsRequestSerial;
  const root=q('#subscription-list');
  try{
    const data=await api('/api/cli-bridge/status');
    // Several dashboard features can refresh this endpoint at the same time
    // (initial page load, account-pool refresh, and the Bridge switch). Do
    // not let a slower response from before a mode change overwrite the
    // newer runtime/selection state.
    if(requestSerial<subscriptionsAppliedSerial)return data;
    subscriptionsAppliedSerial=requestSerial;
    state.subscriptionsData=data;
    const items=[['antigravity','Antigravity'],['grok','Grok'],['claude','Claude'],['cursor','Cursor']];
    if(!root)return;
    root.innerHTML=items.map(function(item){
      const key=item[0],label=item[1],info=data[key]||{},
        detected=Boolean(info.detected),
        imported=Boolean(info.imported||info.active),
        active=Boolean(info.active),
        pending=Array.isArray(info.accounts)&&info.accounts.some(function(account){return account.auth_status==='missing'}),
        stateLabel=active?'模型已导入':imported?'已导入 · 等待 Bridge':detected?'已发现登录态':pending?'登录流程中':'未添加账号',
        poolSummary=subscriptionPoolSummary(info,detected,active),
        action=imported||detected
          ?'<button type="button" class="button" data-subscription="'+key+'">'+(imported?'重新导入模型':'导入模型')+'</button>'
          :'<button type="button" class="button" data-oauth-add="'+key+'">添加登录账号</button>';
      return '<div class="subscription-row"><div class="provider-symbol">'+subscriptionIcon(key)+'</div><div class="provider-copy"><b>'+esc(label)+'</b><span>'+esc(poolSummary+' · '+(active?'模型目录已建立并已暴露':imported?'模型目录已建立，开启 Bridge 后可用':detected?'登录账号已发现，可导入模型':pending?'请完成登录后等待账号就绪':'先添加登录账号，再导入模型'))+'</span></div><span class="status '+(active?'good':imported||detected?'warn':'')+'">'+stateLabel+'</span>'+action+'</div>';
    }).join('');
    document.querySelectorAll('[data-subscription]').forEach(function(el){el.onclick=function(){activateSubscription(el.dataset.subscription)}});
  }catch(error){
    if(root)root.innerHTML='<div class="empty">无法检测本机订阅：'+esc(error.message)+'</div>';
    throw error;
  }
}

async function activateSubscription(name){const button=q('[data-subscription="'+esc(name)+'"]');try{await runButton(button,{loading:'导入模型中…',success:'模型已导入',failure:'模型导入失败'},async function(){await post('/api/cli-bridge/activate',{cli:name});await syncDashboardState()});toast(name+' 模型目录已导入')}catch(e){toast(e.message,true)}}
