function findProviderForModel(model){const providerKey=model.backend_provider||model.provider;const found=state.providers.find(function(p){return p.id===providerKey||p.preset_id===providerKey})||state.providers.find(function(p){return (p.active_models||[]).some(function(m){return m.id===model.id})});if(found)return found;const subData=state.subscriptionsData&&state.subscriptionsData[providerKey];if(subData){return {id:providerKey,status:subData.active?'active':(subData.detected?'configured':'not_configured'),test_status:subData.test_status||'untested',test_message:subData.test_message||''}}return {id:providerKey,status:'configured',test_status:'untested'}}
function renderEnabledModels(){const root=q('#enabled-models');const restart=q('#restart-button');if(!root)return;const staged=state.models.filter(function(m){return true});if(restart){restart.disabled=!staged.length;restart.title=staged.length?(state.gatewayActive?'重启 Codex 后保持 Desktop Bridge，并将模型写入 Desktop 菜单':'检测到第三方模型，重启 Codex 时将自动开启 Desktop Bridge'):'添加至少一个第三方模型后才可重启'}if(!staged.length){root.innerHTML='<div class="empty">尚未添加第三方模型。先保存 API Key，或导入本机订阅。</div>';return}root.innerHTML=staged.map(function(model){const mid=model.slug||model.id;const provider=findProviderForModel(model);const providerId=provider&&provider.id;const providerStatus=provider&&provider.test_status||'untested';const connected=['connected','simulated'].includes(providerStatus);const failed=providerStatus==='failed';const statusLabel=connected?'已连接':failed?'连接失败':'待测试';const statusClass=connected?'good':failed?'error':'pending';return '<div class="model-row"><div class="model-name"><div class="model-icon">'+esc(String(model.display_name||mid).slice(0,1).toUpperCase())+'</div><div><b>'+esc(model.display_name||mid)+'</b><span>'+esc(mid)+'</span></div></div><span class="model-state '+statusClass+'">'+statusLabel+'</span><span><button class="button" data-test-model="'+esc(providerId||model.backend_provider||'')+'">'+(connected?'重新测试':'测试连接')+'</button> <button class="button" data-delete-model="'+esc(mid)+'">删除</button></span></div>'}).join('');document.querySelectorAll('[data-test-model]').forEach(function(el){el.onclick=function(){if(el.dataset.testModel)testProvider(el.dataset.testModel,el);else toast('该模型没有可测试的服务商',true)}});document.querySelectorAll('[data-delete-model]').forEach(function(el){el.onclick=function(){deleteModel(el.dataset.deleteModel,el)}})}

function syncVoiceFields(){const sttApi=q('#stt-engine').value==='openai-compatible'||q('#stt-engine').value==='groq';q('#stt-local-fields').classList.toggle('hidden',sttApi);q('#stt-api-fields').classList.toggle('hidden',!sttApi);const engine=q('#tts-engine').value;const ttsApi=['openai-compatible','doubao','minimax','mimo'].includes(engine);q('#tts-api-fields').classList.toggle('hidden',!ttsApi);q('#tts-doubao-fields').classList.toggle('hidden',engine!=='doubao');const ttsUrl=q('#tts-base-url'),ttsModel=q('#tts-model'),ttsKey=q('#tts-api-key'),voice=q('#tts-voice');if(engine==='doubao'){ttsUrl.placeholder='https://openspeech.bytedance.com/api/v3/tts/unidirectional';ttsModel.placeholder='seed-tts-2.0-expressive';ttsKey.placeholder='Volcengine API Key'}else if(engine==='minimax'){ttsUrl.placeholder='https://api.minimaxi.com';ttsModel.placeholder='speech-2.8-turbo';ttsKey.placeholder='MiniMax API Key';voice.placeholder='female-shaonv'}else if(engine==='mimo'){ttsUrl.placeholder='https://api.xiaomimimo.com';ttsModel.placeholder='mimo-v2.5-tts';ttsKey.placeholder='MiMo API Key';voice.placeholder='Chloe'}else{ttsUrl.placeholder='https://api.openai.com/v1';ttsModel.placeholder='tts-1';ttsKey.placeholder='API Key';voice.placeholder=engine==='edge-tts'?'en-US-AvaNeural':'alloy'}translatePage()}
